//! Regression test: every generated compatibility response must be a
//! well-formed TL object that the declared return type can parse back.
//!
//! Generated by `tools/gen_compat.py`; do not edit by hand.

use grammers_tl_types as tl;
use grammers_tl_types::Deserializable;
use telegram_server::compat;

fn roundtrip<T: Deserializable>(ctor: u32, label: &str) {
    let body = compat::default_response(ctor)
        .unwrap_or_else(|| panic!("{label}: no default response for {ctor:#x}"));
    let mut cur = tl::Cursor::from_slice(&body);
    T::deserialize(&mut cur)
        .unwrap_or_else(|e| panic!("{label}: {ctor:#x} is not valid TL: {e:?}"));
    assert_eq!(
        cur.pos(),
        body.len(),
        "{label}: {ctor:#x} left trailing bytes"
    );
}

