#[test]
fn excluded_namespaces_are_not_stubbed() {
    for ctor in [0x00000000u32, 0xffffffffu32] {
        assert!(compat::default_response(ctor).is_none());
    }
    for ns in compat::UNSUPPORTED_NAMESPACES {
        assert!([
            "aicompose",
            "fragment",
            "payments",
            "phone",
            "premium",
            "smsjobs"
        ]
        .contains(ns));
    }
    // Excluded methods must not appear in the compatibility table.
    let stubbed: Vec<u32> = vec![
        0x32512c5, 0x41845db, 0x42f1f61, 0x93fa0bf, 0xbe77b4a, 0xd6b48f7, 0xedc39d0, 0xf91b065,
        0x10a698e8, 0x1513e7b0, 0x1782cbb1, 0x17d54f61, 0x1ab21940, 0x1c50d144, 0x1ca6ac0a,
        0x1dbfeca0, 0x1f4a0e87, 0x219c34e6, 0x227d824b, 0x2433dc92, 0x2478d1cc, 0x25ae8f4a,
        0x2757ba54, 0x277add7e,
    ];
    for ctor in stubbed {
        assert!(
            compat::default_response(ctor).is_none(),
            "{ctor:#x} should not be stubbed"
        );
    }
}
